programa
{
    funcao inteiro soma_entre(inteiro menor, inteiro maior)
    {
        inteiro soma = 0
        inteiro i
        inteiro novo_maior = maior + 1

        para (i = menor; i < novo_maior; i++)
        {
            soma = soma + i
        }
        retorne soma
    }

    funcao inicio()
    {
        inteiro a, b
        escreva("Digite dois numeros inteiros: ")
        leia(a)
        leia(b)
        escreva("Soma = ", soma_entre(a, b), "\n")
    }
}
